/** Phase 1 must preserve live combat, not inherit the rejected timing/movement prototype.
 * Frozen hashes generated by replaying unmodified commit
 * 1be61e19818ffab9bb6962cde8d592d49feac5f8 at 60 fixed ticks/second.
 * Hashes include every state field (RNG, contacts, effects, HP, outcomes, etc.)
 * except presentation-only alpha/prevFrontLine/prevX/prevY. Do not regenerate from a candidate.
 */
import { authoritativeState } from './helpers/presentation-state.mjs';
import test from 'node:test';
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { readFileSync, existsSync } from 'node:fs';
import { createGame, step, setPlayerInput } from '../dist/sim.js';

function canonical(value) {
  if (Array.isArray(value)) return value.map(canonical);
  if (value && typeof value === 'object') return Object.fromEntries(Object.keys(value).sort()
    .map(key => [key, canonical(value[key])]));
  return value;
}
const hash = value => createHash('sha256').update(JSON.stringify(canonical(authoritativeState(value)))).digest('hex');
function setup(scenario) {
  const game = createGame(scenario.seed, scenario.options);
  if (scenario.name === 'controlled') setPlayerInput(game, { moveX: 1, moveY: .3, attack: true, force: true, guard: false, dash: true });
  return game;
}

