for (const scenario of LIVE_BASELINES) {
  test(`Phase 1 exact live combat/RNG/contact/outcome baseline: ${scenario.name}`, () => {
    const game = setup(scenario);
    let elapsedTicks = 0;
    for (const checkpoint of scenario.checkpoints) {
      while (elapsedTicks < checkpoint.requestedTick) { step(game, 1 / 60); elapsedTicks++; }
      assert.equal(game.tick, checkpoint.actualTick);
      assert.equal(hash(game), checkpoint.hash, `all non-presentation state at tick ${game.tick}`);
    }
    assert.equal(game.rngState, scenario.rng);
    assert.equal(game.status, scenario.status);
    assert.equal(game.winner, scenario.winner);
    assert.deepEqual(game.score, scenario.score);
  });

  test(`Phase 1 60/120/144 Hz partitions are exact at common fixed ticks: ${scenario.name}`, () => {
    const games = [60, 120, 144].map(hz => ({ hz, game: setup(scenario) }));
    // Five fixed ticks = 5/10/12 frames: no fractional checkpoint ambiguity.
    for (let chunk = 0; chunk < 360; chunk++) {
      for (const { hz, game } of games) for (let frame = 0; frame < hz / 12; frame++) step(game, 1 / hz);
      const expected = hash(games[0].game);
      for (const { hz, game } of games.slice(1)) {
        assert.equal(game.tick, games[0].game.tick, `${hz} Hz tick`);
        assert.equal(hash(game), expected, `${hz} Hz full state at tick ${game.tick}`);
      }
    }
  });
}

test('Phase 6 raises the presentation frame clamp while excluding rejected prototype logic', () => {
  const app = readFileSync(new URL('../dist/app.js', import.meta.url), 'utf8');
  assert.match(app, /Math\.min\(\.25,\s*\(now - lastTime\)\s*\/\s*1000\)/);
  for (const file of ['app.js', 'sim.js', 'choreography.js', 'combat-sequences.js', 'pose-rig.js']) {
    const source = readFileSync(new URL(`../dist/${file}`, import.meta.url), 'utf8');
    assert.doesNotMatch(source, /(?:from\s*|import\s*\()["'][^"']*(?:attack-timing|locomotion)\.js/);
  }
  assert.equal(existsSync(new URL('../dist/attack-timing.js', import.meta.url)), false);
  assert.equal(existsSync(new URL('../dist/locomotion.js', import.meta.url)), false);
});
